-- RentalPS Manager / initial schema for Supabase. Run in SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Asia/Jakarta',currency text not null default 'IDR',settings jsonb not null default '{"warning_thresholds_min":[10,5],"overtime_tolerance_min":5,"rounding_rule_minutes":15}'::jsonb,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.business_members(business_id uuid not null references public.businesses(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','admin','operator')),is_active boolean not null default true,created_at timestamptz not null default now(),primary key(business_id,user_id));
create table if not exists public.units(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,code varchar(10) not null,name varchar(40) not null,console_type text not null check(console_type in ('PS3','PS4','PS5','Lainnya')),room text not null default 'Reguler',controller_count smallint not null default 2 check(controller_count between 1 and 4),default_hourly_rate numeric(12,0) not null default 10000,status text not null default 'available' check(status in ('available','maintenance')),notes varchar(200),is_active boolean not null default true,deleted_at timestamptz,created_at timestamptz not null default now(),unique(business_id,code));
create table if not exists public.rate_plans(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,billing_type text not null check(billing_type in ('hourly','package','open')),console_type text not null default 'Lainnya',room text not null default 'Reguler',duration_minutes integer,price numeric(12,0) not null check(price>0),price_per_hour numeric(12,0) not null check(price_per_hour>0),rounding_rule_minutes integer not null default 15 check(rounding_rule_minutes in (0,15,30,60)),overtime_tolerance_minutes integer not null default 5,is_active boolean not null default true,valid_from date,valid_to date,created_at timestamptz not null default now());
create table if not exists public.sessions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,unit_id uuid not null references public.units(id) on delete restrict,rate_plan_id uuid references public.rate_plans(id) on delete set null,customer_name varchar(60),billing_type text not null check(billing_type in ('package','hourly','open')),status text not null default 'active' check(status in ('active','paused','overtime','completed','cancelled')),started_at timestamptz not null default now(),planned_end_at timestamptz,paused_at timestamptz,ended_at timestamptz,total_paused_seconds integer not null default 0,subtotal numeric(12,0) not null default 0,discount numeric(12,0) not null default 0,total numeric(12,0) not null default 0,payment_status text not null default 'unpaid' check(payment_status in ('unpaid','partial','paid')),rate_snapshot jsonb not null default '{}'::jsonb,notes varchar(200),created_by uuid references auth.users(id) on delete set null,ended_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create unique index if not exists sessions_one_open_session_per_unit on public.sessions(unit_id) where status in ('active','paused','overtime');
create index if not exists sessions_business_started_idx on public.sessions(business_id,started_at desc);
create table if not exists public.session_pauses(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.sessions(id) on delete cascade,paused_at timestamptz not null default now(),resumed_at timestamptz,reason varchar(200),created_by uuid references auth.users(id) on delete set null);
create table if not exists public.session_events(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,session_id uuid not null references public.sessions(id) on delete cascade,event_type text not null,payload jsonb not null default '{}'::jsonb,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,session_id uuid not null references public.sessions(id) on delete restrict,method text not null check(method in ('cash','transfer','qris','other')),amount numeric(12,0) not null check(amount>=0),received_amount numeric(12,0) not null check(received_amount>=amount),change_amount numeric(12,0) not null default 0,paid_at timestamptz not null default now(),received_by uuid references auth.users(id) on delete set null);
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,action text not null,entity text not null,entity_id uuid,before_data jsonb,after_data jsonb,reason text,created_at timestamptz not null default now());
create or replace function public.is_business_member(p_business_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.business_members m where m.business_id=p_business_id and m.user_id=auth.uid() and m.is_active); $$;
create or replace function public.current_business_role(p_business_id uuid) returns text language sql stable security definer set search_path=public as $$ select m.role from public.business_members m where m.business_id=p_business_id and m.user_id=auth.uid() and m.is_active limit 1; $$;
create or replace function public.start_rental_session(p_unit_id uuid,p_rate_plan_id uuid default null,p_customer_name text default null,p_billing_type text default 'package',p_duration_minutes integer default 60,p_rate_per_hour numeric default 10000) returns uuid language plpgsql security definer set search_path=public as $$ declare u public.units%rowtype; r public.rate_plans%rowtype; s public.sessions%rowtype; mins integer; rate numeric(12,0); price numeric(12,0); snap jsonb; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; select * into u from public.units where id=p_unit_id and is_active and deleted_at is null for update; if not found then raise exception 'UNIT_NOT_FOUND'; end if; if not public.is_business_member(u.business_id) then raise exception 'FORBIDDEN'; end if; if u.status='maintenance' then raise exception 'UNIT_MAINTENANCE'; end if; if exists(select 1 from public.sessions where unit_id=u.id and status in ('active','paused','overtime')) then raise exception 'UNIT_BUSY'; end if; mins:=case when p_billing_type='open' then null else coalesce(p_duration_minutes,60) end; rate:=coalesce(p_rate_per_hour,u.default_hourly_rate); price:=case when p_billing_type='open' then 0 else round(rate*coalesce(mins,60)/60.0) end; if p_rate_plan_id is not null then select * into r from public.rate_plans where id=p_rate_plan_id and business_id=u.business_id and is_active; if not found then raise exception 'RATE_PLAN_NOT_FOUND'; end if; rate:=r.price_per_hour; price:=case when p_billing_type='open' then 0 when p_billing_type='package' and r.billing_type='package' and r.duration_minutes=mins then r.price else round(rate*coalesce(mins,60)/60.0) end; snap:=jsonb_build_object('rate_plan_id',r.id,'name',r.name,'price',price,'price_per_hour',rate,'rounding_rule_minutes',r.rounding_rule_minutes,'overtime_tolerance_minutes',r.overtime_tolerance_minutes); else snap:=jsonb_build_object('price',price,'price_per_hour',rate,'rounding_rule_minutes',15,'overtime_tolerance_minutes',5); end if; insert into public.sessions(business_id,unit_id,rate_plan_id,customer_name,billing_type,status,started_at,planned_end_at,subtotal,total,payment_status,rate_snapshot,created_by) values(u.business_id,u.id,p_rate_plan_id,nullif(trim(p_customer_name),''),p_billing_type,'active',now(),case when mins is null then null else now()+make_interval(mins=>mins) end,price,price,'unpaid',snap,auth.uid()) returning * into s; insert into public.session_events(business_id,session_id,event_type,payload,created_by) values(u.business_id,s.id,'start',jsonb_build_object('unit_id',u.id,'planned_end_at',s.planned_end_at,'total',s.total),auth.uid()); insert into public.audit_logs(business_id,user_id,action,entity,entity_id,after_data) values(u.business_id,auth.uid(),'session.started','session',s.id,to_jsonb(s)); return s.id; exception when unique_violation then raise exception 'UNIT_BUSY'; end; $$;
create or replace function public.extend_rental_session(p_session_id uuid,p_minutes integer) returns public.sessions language plpgsql security definer set search_path=public as $$ declare s public.sessions%rowtype; u public.units%rowtype; rate numeric(12,0); fee numeric(12,0); ends timestamptz; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if p_minutes<5 or p_minutes>720 then raise exception 'INVALID_DURATION'; end if; select * into s from public.sessions where id=p_session_id for update; if not found or not public.is_business_member(s.business_id) then raise exception 'FORBIDDEN'; end if; if s.status not in ('active','overtime') or s.planned_end_at is null then raise exception 'SESSION_NOT_ACTIVE_OR_OPEN_BILLING'; end if; select * into u from public.units where id=s.unit_id; rate:=coalesce((s.rate_snapshot->>'price_per_hour')::numeric,u.default_hourly_rate); fee:=round(rate*p_minutes/60.0); ends:=(case when s.planned_end_at<now() then now() else s.planned_end_at end)+make_interval(mins=>p_minutes); update public.sessions set status='active',planned_end_at=ends,subtotal=subtotal+fee,total=total+fee where id=s.id returning * into s; insert into public.session_events(business_id,session_id,event_type,payload,created_by) values(s.business_id,s.id,'extend',jsonb_build_object('minutes',p_minutes,'fee',fee,'planned_end_at',ends),auth.uid()); return s; end; $$;
create or replace function public.pause_rental_session(p_session_id uuid,p_reason text default null) returns public.sessions language plpgsql security definer set search_path=public as $$ declare s public.sessions%rowtype; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; select * into s from public.sessions where id=p_session_id for update; if not found or not public.is_business_member(s.business_id) then raise exception 'FORBIDDEN'; end if; if s.status not in ('active','overtime') then raise exception 'SESSION_NOT_ACTIVE'; end if; update public.sessions set status='paused',paused_at=now() where id=s.id returning * into s; insert into public.session_pauses(session_id,paused_at,reason,created_by) values(s.id,s.paused_at,nullif(trim(p_reason),''),auth.uid()); insert into public.session_events(business_id,session_id,event_type,payload,created_by) values(s.business_id,s.id,'pause',jsonb_build_object('paused_at',s.paused_at,'reason',p_reason),auth.uid()); return s; end; $$;
create or replace function public.resume_rental_session(p_session_id uuid) returns public.sessions language plpgsql security definer set search_path=public as $$ declare s public.sessions%rowtype; elapsed integer; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; select * into s from public.sessions where id=p_session_id for update; if not found or not public.is_business_member(s.business_id) then raise exception 'FORBIDDEN'; end if; if s.status<>'paused' or s.paused_at is null then raise exception 'SESSION_NOT_PAUSED'; end if; elapsed:=greatest(0,floor(extract(epoch from now()-s.paused_at))::integer); update public.sessions set status=case when planned_end_at is not null and planned_end_at+make_interval(secs=>elapsed)<now() then 'overtime' else 'active' end,planned_end_at=case when planned_end_at is null then null else planned_end_at+make_interval(secs=>elapsed) end,total_paused_seconds=total_paused_seconds+elapsed,paused_at=null where id=s.id returning * into s; update public.session_pauses set resumed_at=now() where session_id=s.id and resumed_at is null; insert into public.session_events(business_id,session_id,event_type,payload,created_by) values(s.business_id,s.id,'resume',jsonb_build_object('elapsed_seconds',elapsed,'planned_end_at',s.planned_end_at),auth.uid()); return s; end; $$;
create or replace function public.end_rental_session(p_session_id uuid,p_payment_method text default 'cash',p_received_amount numeric default 0) returns jsonb language plpgsql security definer set search_path=public as $$ declare s public.sessions%rowtype; total_due numeric(12,0); mins integer; fee numeric(12,0):=0; rate numeric(12,0); received numeric(12,0); applied numeric(12,0); change_due numeric(12,0); tol integer; rounding integer; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if p_payment_method not in ('cash','transfer','qris','other') then raise exception 'INVALID_PAYMENT_METHOD'; end if; select * into s from public.sessions where id=p_session_id for update; if not found or not public.is_business_member(s.business_id) then raise exception 'FORBIDDEN'; end if; if s.status not in ('active','paused','overtime') then raise exception 'SESSION_NOT_ACTIVE'; end if; rate:=coalesce((s.rate_snapshot->>'price_per_hour')::numeric,0); tol:=coalesce((s.rate_snapshot->>'overtime_tolerance_minutes')::integer,5); rounding:=coalesce((s.rate_snapshot->>'rounding_rule_minutes')::integer,15); if s.billing_type='open' then mins:=greatest(1,ceil(greatest(0,extract(epoch from now()-s.started_at)-s.total_paused_seconds)/60.0)::integer); if rounding>0 then mins:=ceil(mins::numeric/rounding)::integer*rounding; end if; fee:=round(rate*mins/60.0); elsif s.status<>'paused' and s.planned_end_at is not null then mins:=greatest(0,ceil(extract(epoch from now()-s.planned_end_at)/60.0)::integer-tol); if mins>0 then if rounding>0 then mins:=ceil(mins::numeric/rounding)::integer*rounding; end if; fee:=round(rate*mins/60.0); end if; end if; total_due:=greatest(0,s.subtotal+fee-s.discount); received:=greatest(0,coalesce(p_received_amount,0)); applied:=least(total_due,received); change_due:=greatest(0,received-total_due); update public.sessions set status='completed',ended_at=now(),ended_by=auth.uid(),total=total_due,payment_status=case when applied>=total_due then 'paid' when applied>0 then 'partial' else 'unpaid' end where id=s.id returning * into s; if received>0 then insert into public.payments(business_id,session_id,method,amount,received_amount,change_amount,received_by) values(s.business_id,s.id,p_payment_method,applied,received,change_due,auth.uid()); end if; insert into public.session_events(business_id,session_id,event_type,payload,created_by) values(s.business_id,s.id,'end',jsonb_build_object('overtime_fee',fee,'total',total_due,'payment_status',s.payment_status),auth.uid()); insert into public.audit_logs(business_id,user_id,action,entity,entity_id,after_data) values(s.business_id,auth.uid(),'session.ended','session',s.id,to_jsonb(s)); return jsonb_build_object('session_id',s.id,'total',total_due,'overtime_fee',fee,'applied',applied,'received',received,'change',change_due,'payment_status',s.payment_status); end; $$;
alter table public.businesses enable row level security; alter table public.business_members enable row level security; alter table public.units enable row level security; alter table public.rate_plans enable row level security; alter table public.sessions enable row level security; alter table public.session_pauses enable row level security; alter table public.session_events enable row level security; alter table public.payments enable row level security; alter table public.audit_logs enable row level security;
create policy "members read business" on public.businesses for select to authenticated using(public.is_business_member(id));
create policy "owners update business" on public.businesses for update to authenticated using(public.current_business_role(id)='owner') with check(public.current_business_role(id)='owner');
create policy "members read memberships" on public.business_members for select to authenticated using(public.is_business_member(business_id));
create policy "members read units" on public.units for select to authenticated using(public.is_business_member(business_id));
create policy "admins update units" on public.units for update to authenticated using(public.is_business_member(business_id) and public.current_business_role(business_id) in ('owner','admin')) with check(public.is_business_member(business_id) and public.current_business_role(business_id) in ('owner','admin'));
create policy "members read rate plans" on public.rate_plans for select to authenticated using(public.is_business_member(business_id));
create policy "admins manage rates" on public.rate_plans for all to authenticated using(public.is_business_member(business_id) and public.current_business_role(business_id) in ('owner','admin')) with check(public.is_business_member(business_id) and public.current_business_role(business_id) in ('owner','admin'));
create policy "members read sessions" on public.sessions for select to authenticated using(public.is_business_member(business_id));
create policy "members read pauses" on public.session_pauses for select to authenticated using(exists(select 1 from public.sessions s where s.id=session_id and public.is_business_member(s.business_id)));
create policy "members read events" on public.session_events for select to authenticated using(public.is_business_member(business_id));
create policy "members read payments" on public.payments for select to authenticated using(public.is_business_member(business_id));
create policy "admins read audit" on public.audit_logs for select to authenticated using(public.is_business_member(business_id) and public.current_business_role(business_id) in ('owner','admin'));
revoke all on function public.start_rental_session(uuid,uuid,text,text,integer,numeric) from public; revoke all on function public.extend_rental_session(uuid,integer) from public; revoke all on function public.pause_rental_session(uuid,text) from public; revoke all on function public.resume_rental_session(uuid) from public; revoke all on function public.end_rental_session(uuid,text,numeric) from public;
grant execute on function public.start_rental_session(uuid,uuid,text,text,integer,numeric) to authenticated; grant execute on function public.extend_rental_session(uuid,integer) to authenticated; grant execute on function public.pause_rental_session(uuid,text) to authenticated; grant execute on function public.resume_rental_session(uuid) to authenticated; grant execute on function public.end_rental_session(uuid,text,numeric) to authenticated;
do $$ begin execute 'alter publication supabase_realtime add table public.units'; exception when duplicate_object then null; when undefined_object then null; end $$; do $$ begin execute 'alter publication supabase_realtime add table public.sessions'; exception when duplicate_object then null; when undefined_object then null; end $$; do $$ begin execute 'alter publication supabase_realtime add table public.payments'; exception when duplicate_object then null; when undefined_object then null; end $$;
